// Checks only a small version manifest; never evaluates downloaded code.
(() => {
    const current='0.1.48';
    const manifest='https://raw.githubusercontent.com/Truciaczek/Motyw/main/version.json';
    const install='https://github.com/Truciaczek/Motyw/raw/refs/heads/main/dist/motyw.user.js';
    const valid=v=>typeof v==='string' && /^\d{1,6}\.\d{1,6}\.\d{1,6}$/.test(v);
    function newer(a,b){
        if(!valid(a)||!valid(b))return false;
        const x=a.split('.').map(Number),y=b.split('.').map(Number);
        for(let i=0;i<3;i++)if(x[i]!==y[i])return x[i]>y[i];
        return false;
    }
    let stopped=false,request=null,host=null,timer=null,busy=false;
    const dismissedKey='truciak:theme:update-dismissed:v1';
    function show(version){
        if(stopped || host || !document.body)return;
        let dismissed;try{dismissed=GM_getValue(dismissedKey,null);}catch{}
        if(dismissed?.version===version && dismissed.until>Date.now())return;
        host=document.createElement('div');host.id='truciak-theme-update-notice';
        const root=host.attachShadow({mode:'open'});
        root.innerHTML=`<style>:host{all:initial;position:fixed;right:18px;bottom:18px;z-index:2147483647;font:14px/1.45 Arial;color:#dce6ee}section{box-sizing:border-box;width:330px;max-width:calc(100vw - 36px);padding:16px;background:#171b20;border:1px solid #12c9bd;border-radius:6px;box-shadow:0 8px 28px #0009}h2{font-size:16px;margin:0 0 8px}p{margin:0 0 14px;color:#c7d0d9}nav{display:flex;gap:10px}a,button{font:inherit;cursor:pointer;padding:7px 12px;border:1px solid #668298;border-radius:4px;text-decoration:none;color:#dce6ee;background:#252b31}a{border-color:#12c9bd;color:#12c9bd}:focus-visible{outline:2px solid #12c9bd;outline-offset:3px}</style><section role="dialog" aria-modal="false" aria-labelledby="update-title"><h2 id="update-title">Dostępna nowa wersja motywu</h2><p class="version"></p><nav><a target="_blank" rel="noopener noreferrer">Aktualizuj</a><button type="button">Później</button></nav></section>`;
        root.querySelector('.version').textContent='Wersja '+current+' → '+version+'. Potwierdź aktualizację w Tampermonkey, a potem odśwież grę.';
        root.querySelector('a').href=install;
        root.querySelector('button').onclick=()=>{
            try{GM_setValue(dismissedKey,{version,until:Date.now()+24*60*60*1000});}catch{}
            host?.remove();host=null;
        };
        document.body.appendChild(host);
    }
    function check(){
        if(stopped || busy || host)return;
        busy=true;
        try{request=GM_xmlhttpRequest({method:'GET',url:manifest+'?t='+Date.now(),timeout:10000,
            onload(response){busy=false;
                if(stopped || response.status!==200 || response.responseText.length>4096)return;
                try{const data=JSON.parse(response.responseText);if(newer(data.version,current))show(data.version);}catch{}
            },onerror(){busy=false;},ontimeout(){busy=false;},onabort(){busy=false;}
        });}catch{busy=false;}
    }
    function start(){if(stopped)return;check();timer=window.setInterval(check,30*60*1000);}
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
    window.addEventListener('pagehide',()=>{stopped=true;window.clearInterval(timer);request?.abort?.();host?.remove();host=null;},{once:true});
})();

// Same 5 px launcher gap and 8 px viewport margin as Firuś.
function truciakMenuGeometry(anchor, width, viewport, corner = '') {
    const margin=8, gap=5;
    const onLeft=corner ? corner.endsWith('left') : (anchor.left+anchor.width/2 < viewport.width/2);
    const upwards=corner ? corner.startsWith('bottom') : (anchor.top+anchor.height/2 >= viewport.height/2);
    const desiredLeft=onLeft ? anchor.left : anchor.right-width;
    const left=Math.max(margin,Math.min(desiredLeft,viewport.width-width-margin));
    const available=upwards ? anchor.top-gap-margin : viewport.height-anchor.bottom-gap-margin;
    return {left:(left-anchor.left)+'px',right:'auto',maxHeight:Math.max(0,available)+'px',
        top:upwards?'auto':(anchor.height+gap)+'px',bottom:upwards?(anchor.height+gap)+'px':'auto'};
}
function placeTruciakMenu(panel, anchor, tile) {
    const container=tile?.closest?.('.main-buttons-container');
    const corner=['top-left','top-right','bottom-left','bottom-right'].find(c=>container?.classList?.contains(c)) || '';
    Object.assign(panel.style,truciakMenuGeometry(anchor,panel.offsetWidth,{width:window.innerWidth,height:window.innerHeight},corner));
}

// Both independent launchers share one NI widget manager. Registration must
// include its complete persisted layout and must not finish a user drag session.
function installTruciakLauncherCoexistence(window) {
    const keys = new Set(['truciak_addonsManager', 'truciak_private_addonsManager', 'gogatki_addonsManager']);
    const patched = new WeakSet();
    const valid = p => Array.isArray(p) && Number.isInteger(p[0]) && p[0] >= 0 && typeof p[1] === 'string' && !!p[1].trim();
    function attach() {
        const manager = window.Engine?.widgetManager;
        if (!manager || patched.has(manager) || typeof manager.createOneWidget !== 'function') return;
        const original = manager.createOneWidget;
        const finish = manager.setEnableDraggingButtonsWidget;
        let registrationTurn = false;
        const initialized = new Set();
        manager.createOneWidget = function(key, layout, ...args) {
            if (this !== manager || !keys.has(key) || args[0] !== true || initialized.has(key)) {
                return original.call(this, key, layout, ...args);
            }
            let saved;
            try { saved = window.Engine?.serverStorage?.get(manager.getPathToHotWidgetVersion()); } catch {}
            const full = saved && typeof saved === 'object' && !Array.isArray(saved) ? {...saved} : {};
            const position = valid(full[key]) ? [...full[key]] : layout?.[key];
            if (valid(position)) full[key] = [...position];
            const set = manager.getDefaultWidgetSet?.();
            // Align registered addon defaults before NI (or the other launcher)
            // checks them. Never change unrelated widgets or server storage.
            for (const id of keys) if (set?.[id] && valid(full[id])) {
                set[id].index = full[id][0]; set[id].pos = full[id][1];
            }
            registrationTurn = true;
            window.queueMicrotask(() => { registrationTurn = false; });
            const result = original.call(this, key, full, ...args);
            // A rejected creation must remain retryable.
            if (!args[1]?.includes?.(key)) initialized.add(key);
            return result;
        };
        if (typeof finish === 'function') manager.setEnableDraggingButtonsWidget = function(enabled, ...args) {
            if (this === manager && registrationTurn && enabled === false) return;
            return finish.call(this, enabled, ...args);
        };
        patched.add(manager);
    }
    attach();
    const timer = window.setInterval(attach, 25);
    window.addEventListener('pagehide', () => window.clearInterval(timer), {once:true});
}
installTruciakLauncherCoexistence(window);

